function isoWeek(d) {
  const t = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
  const day = (t.getUTCDay() + 6) % 7; // Mon=0
  t.setUTCDate(t.getUTCDate() - day + 3); // Thursday of this ISO week
  const first = new Date(Date.UTC(t.getUTCFullYear(), 0, 4));
  const fd = (first.getUTCDay() + 6) % 7;
  first.setUTCDate(first.getUTCDate() - fd + 3);
  const week = 1 + Math.round((t - first) / 6048e5);
  return `${t.getUTCFullYear()}-W${String(week).padStart(2, "0")}`;
}
const WINDOWS = {
  hourly: (d) => d.toISOString().slice(0, 13),   // YYYY-MM-DDTHH
  daily: (d) => d.toISOString().slice(0, 10),    // YYYY-MM-DD
  weekly: (d) => isoWeek(d),                     // YYYY-Www (ISO 8601)
};

const rows = items.flatMap((i) => (Array.isArray(i.json) ? i.json : [i.json]));
return rows.map((a) => {
  const at = new Date(a.dispatch_requested_at || Date.now());
  const mapEntry = DISPATCH_MAP[a.slug];
  const windowFn = WINDOWS[a.schedule];
  const window = windowFn ? windowFn(at) : "unscheduled";
  const base = {
    slug: a.slug,
    name: a.name || null,
    autonomy: a.autonomy || null,
    schedule: a.schedule || null,
    run_key: `${a.slug}:${a.schedule}:${window}`,
    dispatch_window: windowFn ? window : null,
    dispatch_requested_at: a.dispatch_requested_at || at.toISOString(),
    idempotency: "run_key",
  };
  if (!mapEntry) return { json: { ...base, decision: "BLOCKED", reason: "unmapped_slug" } };
  base.workflow_file = mapEntry.workflow_file;
  base.live_workflow_id = mapEntry.live_workflow_id;
  if (a.autonomy === "red") return { json: { ...base, decision: "BLOCKED", reason: "manual_only" } };
  if (a.autonomy === "yellow") return { json: { ...base, decision: "APPROVAL_REQUIRED", reason: "autonomy_yellow", approval_route: "pending_approval_queue_design" } };
  if (a.autonomy !== "green") return { json: { ...base, decision: "BLOCKED", reason: "unknown_autonomy" } };
  if (!mapEntry.live_workflow_id) return { json: { ...base, decision: "BLOCKED", reason: "workflow_not_imported" } };
  return { json: { ...base, decision: "DISPATCH_PENDING", reason: "ok" } };
